import os
import sys

def read_blocks(file_path, block_size):
    with open(file_path, 'rb') as f:
        while chunk := f.read(block_size):
            yield chunk

def xor_bytes(b1, b2):
    """XORs two byte strings of equal length."""
    return bytes(a ^ b for a, b in zip(b1, b2))

def invert_parity(parity_block):
    """Invert all bytes in a parity block."""
    return bytes(~b & 0xFF for b in parity_block)

def reconstruct_raid5(data_block_1_path, data_block_2_path, output_path, parity_inverted, block_size):
    with open(output_path, 'wb') as out:
        for block1, block2 in zip(read_blocks(data_block_1_path, block_size),
                                  read_blocks(data_block_2_path, block_size)):
            # Assuming an alternating checkerboard sequence:
            # block1 provides data, block2 contains parity (inverted), or vice versa
            if parity_inverted:
                parity = invert_parity(block2)
                reconstructed = xor_bytes(block1, parity)
            else:
                parity = invert_parity(block1)
                reconstructed = xor_bytes(block2, parity)
            out.write(reconstructed)

