import os

def reconstruct_raid5(images, output_filename):
    block_size = 512  # Sector size in bytes
    inverted_parity = True

    try:
        # Open images for reading
        files = [open(img, "rb") for img in images]

        # Open output file for writing
        with open(output_filename, "wb") as out_fp:
            counter = 0

            while True:
                blocks = []
                for file in files:
                    data = file.read(block_size)
                    if not data:
                        break  # Stop once one file is finished
                    blocks.append(data)

                if not all(blocks):
                    break

                for i, block in enumerate(blocks):
                    if i == (counter % len(blocks)):
                        parity_block = bytearray(block)  # The parity algorithm affects ordering
                        if inverted_parity:
                            for idx in range(block_size):
                                parity_block[idx] = parity_block[idx] ^ 0xFF  # XOR inversion

                        blocks[i] = parity_block

                    out_fp.write(blocks[i])
                counter += 1

        print('Reconstruction completed:', output_filename)
    except Exception as e:
        print(e)
    finally:
        for f in files:
            f.close()

if __name__ == "__main__":
    images = ["/home/ctfplayer/ctf_files/disk.img0", "/home/ctfplayer/ctf_files/disk.img1"]
    output_filename = "/home/ctfplayer/ctf_files/reconstructed.img"
    reconstruct_raid5(images, output_filename)

